public class CatalogFormulaProbe { public static String observedSourceApi(){return '{{API}}';}
    public static Map<String, Object> observe(String row) {
        Map<String, Object> out = new Map<String, Object>{'row' => row};
        try {
            out.put('fixtureCalculated', Ledger__c.LeafText__c.getDescribe().isCalculated());
            out.put('fixtureFormula', Ledger__c.LeafText__c.getDescribe().getCalculatedFormula());
            if (row == 'MC01' || row == 'MC02') {
                String catalog = row == 'MC01' ? 'FieldDefinition' : 'EntityParticle';
                List<SObject> fields = Database.query('SELECT QualifiedApiName, IsCalculated FROM ' + catalog +
                    ' WHERE EntityDefinition.QualifiedApiName = \'Ledger__c\' ORDER BY QualifiedApiName');
                List<Object> flags = new List<Object>();
                for (SObject field : fields) {
                    flags.add(new Map<String, Object>{'name' => field.get('QualifiedApiName'), 'calculated' => field.get('IsCalculated')});
                }
                out.put('fields', flags);
            } else if (row == 'MC09') {
                out.put('ordinaryCalculated', Ledger__c.PlainText__c.getDescribe().isCalculated());
                out.put('ordinaryFormula', Ledger__c.PlainText__c.getDescribe().getCalculatedFormula());
                out.put('standardCalculated', Account.Name.getDescribe().isCalculated());
            } else if (row == 'MC10') {
                Account populated = new Account(Name = 'Populated'); insert populated;
                Account empty = new Account(Name = 'Empty'); insert empty;
                insert new Contact(LastName = 'Child', AccountId = populated.Id);
                Account selected = [SELECT Id, (SELECT LastName FROM Contacts) FROM Account WHERE Id = :populated.Id];
                out.put('populatedSize', selected.getSObjects('Contacts').size());
                selected = [SELECT Id, (SELECT LastName FROM Contacts) FROM Account WHERE Id = :empty.Id];
                out.put('emptyDynamicNull', selected.getSObjects('Contacts') == null);
                out.put('emptyTypedSize', selected.Contacts.size());
                selected = [SELECT Id FROM Account WHERE Id = :populated.Id];
                try {
                    out.put('unselected', selected.getSObjects('Contacts'));
                } catch (Exception e) {
                    out.put('unselectedExceptionType', e.getTypeName());
                    out.put('unselectedExceptionMessage', e.getMessage());
                }
            } else {
                Boolean particles = row == 'MC04' || row == 'MC06' || row == 'MC08';
                Boolean omitted = row == 'MC07' || row == 'MC08';
                Boolean empty = row == 'MC05' || row == 'MC06';
                String relationship = particles ? 'Particles' : 'Fields';
                String selection = omitted ? '' : ', (SELECT DeveloperName, DataType FROM ' + relationship +
                    ' WHERE IsCalculated = true)';
                String parentFilter = empty ? 'QualifiedApiName = \'BareLedger__c\'' :
                    'QualifiedApiName IN (\'Ledger__c\', \'BareLedger__c\')';
                List<SObject> parents = Database.query('SELECT QualifiedApiName' + selection +
                    ' FROM EntityDefinition WHERE ' + parentFilter + ' ORDER BY QualifiedApiName');
                out.put('parentSize', parents.size());
                List<Object> observations = new List<Object>();
                for (SObject parent : parents) {
                    Map<String, Object> observation = new Map<String, Object>{
                        'parent' => parent.get('QualifiedApiName'), 'relationship' => relationship, 'selected' => !omitted
                    };
                    observations.add(observation);
                    try {
                        List<SObject> children = parent.getSObjects(relationship);
                        observation.put('dynamicNull', children == null);
                        observation.put('dynamicSize', children == null ? null : children.size());
                        List<Object> names = new List<Object>();
                        observation.put('children', names);
                        // Deliberately iterate without a null guard: record the
                        // reduced query's outcome separately for every parent.
                        for (SObject field : children) {
                            names.add(new Map<String, Object>{'developerName' => field.get('DeveloperName'), 'dataType' => field.get('DataType')});
                        }
                        observation.put('iterationCompleted', true);
                    } catch (Exception e) {
                        observation.put('exceptionType', e.getTypeName());
                        observation.put('exceptionMessage', e.getMessage());
                    }
                }
                out.put('parents', observations);
            }
        } catch (Exception e) {
            out.put('exceptionType', e.getTypeName());
            out.put('exceptionMessage', e.getMessage());
        }
        return out;
    }
}
